import recipes.models
from django.db import migrations, models


def fill_short_codes(apps, schema_editor):
    """Заполняет короткие коды существующих рецептов."""

    Recipe = apps.get_model('recipes', 'Recipe')

    database = schema_editor.connection.alias

    recipes = Recipe.objects.using(database).all()

    used_codes = set(
        recipes.exclude(
            short_code__isnull=True
        ).exclude(
            short_code=''
        ).values_list('short_code', flat=True)
    )

    for recipe in recipes:
        if recipe.short_code:
            continue

        code = uuid.uuid4().hex[:12]

        while code in used_codes:
            code = uuid.uuid4().hex[:12]

        recipe.short_code = code

        recipe.save(
            using=database,
            update_fields=['short_code'],
        )

        used_codes.add(code)

